Tìm số đo ${x}$ trong hình sau. 

\choice
{ $123^{\circ}$  }
   { \True $133^{\circ}$  }
     {  $138^{\circ}$ }
    {  $143^{\circ}$ }
}{
\begin{tikzpicture}
        % Vẽ các đỉnh của hình tứ giác
        \coordinate (E) at (0, 0);
        \coordinate (F) at (0, 3);
        \coordinate (G) at (2, 4);
        \coordinate (H) at (5, 0);

        % Vẽ các cạnh
        \draw (E) -- (F) -- (G) -- (H) -- cycle;

        % Đánh dấu góc vuông tại điểm E
        \draw (E) rectangle +(0.3, 0.3);

        % Ghi các giá trị góc
        \node at (1.9, 3.5) {$69^\circ$};
        \node at (4.4, 0.3) {$68^\circ$};
        \node at (0.3, 2.8) {$x$};

        % Ghi các điểm E, F, G, H
        \node[below left] at (E) {E};
        \node[above left] at (F) {F};
        \node[above right] at (G) {G};
        \node[below right] at (H) {H};

    \end{tikzpicture}
}
\loigiai{
Vì tổng các góc của một tứ giác bằng $360^\circ$ nên số đo $x$ bằng: $x = 360^\circ - (69^\circ + 68^\circ) = 223^\circ$.
}\end{ex}

